<style scoped lang="scss" src="./fundraiser-info-block.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import Icon from "../icon/icon";
import Meter from "../meter/meter";
import SelectionMenu from '../selection-menu/selection-menu';
import { IconShape } from "../icon/icon.constants";
import { MeterMode } from "../meter/meter.constants";
import { differenceInCalendarDays } from "date-fns";
import ScrollView from "../scroll-view/scroll-view";
import { CurrencyNotation, CurrencyNotationValues } from "../constants";
import { has } from "../../util/has";

/**
 * This is a component to show basic information of a fund
 * It shows days left, introduction and progress of a fund
 */
@Component({
  components: {
    Icon,
    Meter,
    SelectionMenu,
    ScrollView
  }
})
export default class FundraiserInfoBlock extends Vue {
  @Prop({ type: String, default: "" }) tileId;
  @Prop({ type: String, default: "" }) fundName;
  @Prop({ type: [Date, Number, String] }) dueDate;
  @Prop({ type: String, default: "" }) detail;
  @Prop({ type: Number, default: 0 }) collected;
  @Prop({ type: Number, default: 1000 }) goal;
  @Prop({ type: String, default: "" }) image;
  @Prop({ type: String, default: "" }) info;
  @Prop({ type: Boolean, default: true }) showDaysLeft;
  @Prop({ type: Boolean, default: true }) showMeter;
  @Prop({ type: Boolean, default: false }) editing;
  @Prop({ type: Array, default: () => [] }) editItemList;
  @Prop({
    type: String,
    default: CurrencyNotation.USD,
    validator: has(CurrencyNotationValues)
  })
  currency;

  // edit icon
  editIconShape = IconShape.EDIT;
  editIconSize = {
    width: 25
  };
  editIconColor = "#ffffff";
  showEditMenu = false;

  iconShape = IconShape.CALENDAR_CHECK;
  iconSize = {
    width: 15
  };
  iconColor = "#2356f6";
  meterMode = MeterMode.SMALL;

  get daysLeft() {
    let dueDate = this.dueDate;

    if (typeof dueDate === "number" || typeof dueDate === "string") {
      dueDate = new Date(this.dueDate);

      if (dueDate.toDateString() === "Invalid Date") {
        console.warn("Wrong date format");
      }
    }

    const diff = differenceInCalendarDays(dueDate, new Date());

    return diff < 0 ? 0 : diff;
  }

  get contentStyle() {
    if (!this.showMeter) {
      return {
        justifyContent: "flex-start"
      };
    }

    return {
      justifyContent: "space-between"
    };
  }

  handleClick() {
    /**
     * @event click
     */
    this.$emit("click");
  }

  handleEditClick() {
    /**
     * @event edit
     */
    this.$emit("edit", this.tileId);
  }
}
</script>

<template>
  <div @click="this.handleClick" class="FundraiserInfoBlock">
    <div
      class="FundraiserInfoBlock__Image"
      v-bind:style="{ backgroundImage: `url(${image})` }"
    >
      <Icon
        class="FundraiserInfoBlock__EditIcon"
        :shape="editIconShape"
        :size="editIconSize"
        :color="editIconColor"
        @click="handleEditClick"
        v-if="editing"
      />
      <div v-if="Boolean(info)" class="FundraiserInfoBlock__Info">
        <div class="FundraiserInfoBlock__InfoContent">{{ info }}</div>
      </div>
    </div>
    <div class="FundraiserInfoBlock__Lower">
      <div class="FundraiserInfoBlock__Content" :style="contentStyle">
        <div
          v-if="showDaysLeft && daysLeft > 0"
          class="FundraiserInfoBlock__Upper"
        >
          <Icon :shape="iconShape" :size="iconSize" :color="iconColor"></Icon>
          <span class="FundraiserInfoBlock__DaysLeft">
            {{ daysLeft }}
          </span>
          {{ daysLeft === 1 ? "day left" : "days left" }}
        </div>
        <div class="FundraiserInfoBlock__Middle">
          <div class="FundraiserInfoBlock__Name">{{ fundName }}</div>
          <ScrollView>
            <div class="FundraiserInfoBlock__Detail">{{ detail }}</div>
          </ScrollView>
        </div>
        <div class="FundraiserInfoBlock__Lower">
          <Meter
            :collected="collected"
            :goal="goal"
            :mode="meterMode"
            :currency="currency"
          />
        </div>
      </div>
    </div>
  </div>
</template>
